from micropython import const

FLAG = const(0x7E)
MAX_FRAME = const(340)  # AX.25: 2+8 addresses*7 + ctl/pid + 256 info + fcs = 330
MIN_FRAME = const(18)  # dst + src + ctl/pid + fcs


def encode_levels(frame, out, pre_flags=40, post_flags=4, level=0):
    """frame (bytes between flags, incl. FCS) -> NRZI levels written to out (one byte per bit).
    out must be large enough: see levels_size(). level is the NRZI state before the first bit.
    Returns (number of levels written, last level)."""
    n = 0
    lv = level
    for _ in range(pre_flags):
        n, lv = _put_byte(out, n, lv, FLAG)
    ones = 0
    for b in frame:
        for _ in range(8):
            bit = b & 1
            b >>= 1
            if bit:
                out[n] = lv  # 1 = no transition
                n += 1
                ones += 1
                if ones == 5:
                    lv ^= 1  # stuffed 0 = transition
                    out[n] = lv
                    n += 1
                    ones = 0
            else:
                lv ^= 1
                out[n] = lv
                n += 1
                ones = 0
    for _ in range(post_flags):
        n, lv = _put_byte(out, n, lv, FLAG)
    return n, lv


def _put_byte(out, n, lv, b):
    for _ in range(8):
        if not b & 1:
            lv ^= 1
        out[n] = lv
        n += 1
        b >>= 1
    return n, lv


def levels_size(frame_len, pre_flags=40, post_flags=4):
    """Upper bound of encode_levels() output length."""
    nbits = frame_len * 8
    return (pre_flags + post_flags) * 8 + nbits + nbits // 5 + 1


class Deframer:
    """Streaming HDLC deframer. feed() takes data bits (already NRZI-decoded, 0/1 per byte).
    Complete frames (between flags, FCS not checked) are copied into a ring of slots:
        slot = 2-byte little-endian length + MAX_FRAME bytes
    The consumer reads them with get() / done(). head/tail live in a small bytearray so
    producer (core 1) and consumer (core 0) only ever write their own index."""

    def __init__(self, nslots=4):
        self.buf = bytearray(MAX_FRAME)
        self.nslots = nslots
        self.slots = bytearray(nslots * (MAX_FRAME + 2))
        self.idx = bytearray(2)  # [0] = head (producer), [1] = tail (consumer)
        self.overruns = 0
        self.frames = 0
        self.reset()

    def reset(self):
        self.ones = 0
        self.nbits = 0  # data bits in the current frame
        self.acc = 0
        self.hunting = True  # waiting for the first flag

    def feed(self, bits, n):
        """Feed n data bits from bits[0:n]. Returns the number of frames completed."""
        done = 0
        buf = self.buf
        for i in range(n):
            bit = bits[i]
            if bit:
                self.ones += 1
                if self.ones >= 7:  # abort
                    self.hunting = True
                    continue
                if self.ones == 6:  # flag or abort pending, not data
                    continue
            else:
                ones = self.ones
                self.ones = 0
                if ones == 6:  # flag: the last 6 data bits (0 + 5 ones) belonged to it
                    nb = self.nbits - 6
                    if not self.hunting and nb >= MIN_FRAME * 8 and nb % 8 == 0:
                        if self._emit(nb >> 3):
                            done += 1
                    self.hunting = False
                    self.nbits = 0
                    self.acc = 0
                    continue
                if ones == 5:  # stuffed zero
                    continue
            if self.hunting:
                continue
            # data bit, LSB first
            self.acc = (self.acc >> 1) | (bit << 7)
            self.nbits += 1
            if self.nbits & 7 == 0:
                k = (self.nbits >> 3) - 1
                if k >= MAX_FRAME:
                    self.hunting = True
                    continue
                buf[k] = self.acc
        return done

    def _emit(self, length):
        head = self.idx[0]
        nxt = head + 1 if head + 1 < self.nslots else 0
        if nxt == self.idx[1]:
            self.overruns += 1
            return False
        off = head * (MAX_FRAME + 2)
        s = self.slots
        s[off] = length & 0xFF
        s[off + 1] = length >> 8
        s[off + 2 : off + 2 + length] = self.buf[:length]
        self.idx[0] = nxt
        self.frames += 1
        return True

    def get(self):
        """-> memoryview of the oldest complete frame, or None. Call done() after use."""
        tail = self.idx[1]
        if tail == self.idx[0]:
            return None
        off = tail * (MAX_FRAME + 2)
        s = self.slots
        length = s[off] | (s[off + 1] << 8)
        return memoryview(s)[off + 2 : off + 2 + length]

    def done(self):
        tail = self.idx[1]
        self.idx[1] = tail + 1 if tail + 1 < self.nslots else 0
